# frozen_string_literal: true
# Generated by Descant: acceptance tests.

require "rails_helper"
require "open3"

RSpec.describe "Timekeeping handoff test hooks" do
  # "Interrupt and abort hooks load only in the test environment"
  # A defined? check inside this RSpec process cannot fail, because spec/support
  # is loaded here; only a separate process booted as another environment can.
  it "leaves the handoff hook constant undefined when the app boots and eager-loads outside the test environment" do
    script = <<~RUBY
      Rails.application.eager_load!
      print [defined?(Timekeeping::Handoff::Runner).inspect, defined?(TimekeepingHandoffHooks).inspect].join("|")
    RUBY
    env = { "RAILS_ENV" => "development", "SECRET_KEY_BASE_DUMMY" => "1" }

    output, status = Open3.capture2e(env, "bin/rails", "runner", script, chdir: Rails.root.to_s)

    expect(status).to be_success, output
    runner_defined, hooks_defined = output.lines.last.to_s.strip.split("|")
    # The runner itself must load in that process, so the check proves lib/ was eager-loaded.
    expect(runner_defined).to eq('"constant"')
    expect(hooks_defined).to eq("nil")
  end
end
